-- Kenchiko All Remaining Masters Migration (Fixed Quotes)

DROP TABLE IF EXISTS api.master_asobi CASCADE;
DROP TABLE IF EXISTS api.master_ouen_items CASCADE;
DROP TABLE IF EXISTS api.master_ouen_categories CASCADE;
DROP TABLE IF EXISTS api.master_stories CASCADE;
DROP TABLE IF EXISTS api.master_settings CASCADE;

CREATE TABLE api.master_asobi (
    id VARCHAR(100) PRIMARY KEY,
    title TEXT NOT NULL,
    content TEXT DEFAULT '',
    condition VARCHAR(100) DEFAULT '',
    frequency VARCHAR(50) DEFAULT 'normal',
    sort_order INTEGER DEFAULT 0,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE api.master_ouen_categories (
    id VARCHAR(100) PRIMARY KEY,
    label VARCHAR(200) NOT NULL,
    sort_order INTEGER DEFAULT 0,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE api.master_ouen_items (
    id VARCHAR(100) PRIMARY KEY,
    category_id VARCHAR(100) NOT NULL,
    message TEXT NOT NULL,
    sort_order INTEGER DEFAULT 0,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE api.master_stories (
    id INTEGER PRIMARY KEY,
    name VARCHAR(200) NOT NULL,
    kana VARCHAR(200),
    motif VARCHAR(200),
    week_title VARCHAR(200),
    debut_date VARCHAR(50),
    voice TEXT,
    translation TEXT,
    episode_summary TEXT,
    prompt_ja TEXT,
    prompt_en TEXT,
    doc_link TEXT,
    week_info JSONB,
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE api.master_settings (
    key VARCHAR(100) PRIMARY KEY,
    value JSONB NOT NULL,
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

