INSERT INTO api.master_stories (id, name, kana, motif, week_title, debut_date, voice, translation, episode_summary, prompt_ja, prompt_en, doc_link, week_info) VALUES
(265, 'どあとぅーごるふにゃん', 'どあとぅーごるふにゃん', 'インドアゴルフ「DOOR TO GOLF」・シミュレーションゴルフ・コマンド入力', '9月 第2週（2026/09/07 〜 2026/09/11）', '2026/09/09', 'ざーーーーっ！（しゅごごごごっ）', '「伝説のせんじょうこうすいにゃんだにゃ！サインあげるけど雨でインクが全部流れるにゃ！」', '通った後には川しか残らないと恐れられる伝説の有名猫。会員制インドアゴルフ「DOOR TO GOLF」を気に入り長時間滞在したため店舗が浸水危機に。由美さんに頼まれた健介さんが油性ペンと色紙を差し出してサインをもらうが、雨が激しすぎてインクがベタベタに流れてしまった。', 'シンプルなペン画のぽてっとした猫「せんじょうこうすいにゃん」。頭の上に細長く連なる雨雲と激しい土砂降りの雨をまとわせ、インクのにじんだ色紙とペンを抱えてジト目の無表情で立っている脱力系マスコットイラスト。', 'minimalist cute cat mascot named Senjokosui-nyan with a long line of dark rain clouds above its head pouring heavy rain, holding a soggy signature board and pen with a deadpan stoic expression, simple black ink lines --ar 1:1', 'https://docs.google.com/document/d/1WtEILGrq282WUhGhwJ4Ek8xH42VJDQVBvB9R8nppQB4/edit', '{"days":[{"date_header":"2026年9月7日（月）","messages":[{"sender":"由美さん","body":"ふはははー！\nさがのやきはいただいたー！\n\n…\nじょよだんです！\n電子レンジにいれときます！","time":"07:22"},{"body":"きょよはくもってるー\nすずしーなー\n（しゅごごごごーーっ）\n\nしゅゆまつは\n…\nなんかちょっと\nたいへんだったなー\nでもたのしかったなー\n（しゅごごごごーーっ）\n\nうにゃにゃん\n\nきょよはだれ？\nなさすぎてぎゃくに\nよそうがつかない！\n\nえっ？\nどあとぅーごるふにゃん？\n\nあっ、いつもいろいろいるから\nそういえば\nはじめましてかもー\n\nにゃーうにゃーうにゃんにゃにゃ\n\nふんふん\nごるふは\nろうにゃくにゃんにょ\nたのしめる\nすばらしいすぽーつなのに\nちっとも\nとりあげられなくて\nふまんだった？\n\nあっ、うん\nたしかにかなり\nいってるのに\nはつとうじょうだったかも\nごるふの\nれんしゅうぐらいじゃなー\n\nうにゃんにゃうにゃーにゃん\n\nふんふん\nただのれんしゅうじょよじゃない？\nはいてくせつびの\nすーぱーれんしゅうじょう？？\n\nそこまで？\nたしかにえあこんとか\nといれとかそふぁーとか\nおんがくとか\nふつうのごるふじょうには\nないすぺっくではあるけど\n\nにゃーうにゃーうにゃんにゃにゃ\n\nふんふん\nそんなみてくれのとこじゃない？\nもっとすごいきのうが\nまんさいしてる？\n\nえー？\nどこにー？\nそんなのしらなーい\n\nうにゃんにゃにゃうにゃーにゃ\n\nふんふん\nこまんどをにゅうりょくすると\nうらめにゅーがでてくる？？\n\nうらこまんど？\nなんかのげーむ？\nごるふの\nれんしゅゆだよね？\n\nにゃんうにゃーうにゃーにゃ\n\nふんふん\nきーぼーどの\nうえをにかい\nひだりをいっかい\nしたをよんかいおすと\nろしあんるーれっとで\nぼーるがでてくる？\n\nいや、ちゃんと\nまいかいぼーるはだして！\nれんしゅうにならないよ！\n\nうにゃんにゃにゃーにゃうにゃ\n\nふんふん\nほかには\nきーぼーどの\nしたをさんかい\nひだりをにかい\nうえをにかいおすと\n\nつうじょう\nいっきゅうのところ\nなんと\nにきゅうづつでてくる？\n\nいや、いらないし\nあぶないよ！\n\nにゃんうにゃーうにゃんにゃにゃ\n\nふんふん\nさいきょうの\nこまんど\nうえうえしたした\nひだりみぎひだりみぎ\nびーえーをおすと\nうったたまが\nうちかえされて\nもどってくる！\n\nいや、めちゃくちゃ\nきけんだよ！\nけがするよ！\n\nうにゃにゃんにゃーにゃ\n\nふんふん\nうちかえしたら\nさらにこうとくてん？！\n\nいや、\nとくてんとかないから！\nふつうに\nれんしゅうさせて！\n\nあっ、けんちこさん\nれんしゅうは\nおちついてしたいよねー\nなんならかふぇが\nさいこうだよねー\nけーんちーこさーん","time":"07:39","sender":"由美さん"},{"time":"08:25","body":"どきどきどきどき\n\nすぱーん\n（ないすしょっと！）\n\nすぱーん\n（かえってきた？！）\n\nすぱんっ\n（うちかえした！！）\n\nいやー\nすごいなー\nごるふとはおもえないすりる！\nあたらしいとびらをひらいたきがするなー\n\nほかにすごいこまんどないのー\nどあとぅーごるふにゃん！\nなまえながいな！\n\nえー、みぎ、した、みぎしたで\nかんきゃくがふえる？\nこまんどいれただけふやせる？\n\nさいだいごじうにん？？？\n\nいやー\nけんちこそんなににとがいたら\nきんちょうしちゃう…\n\nあ、あ、こまんどいれないで\nそんなてぎわよく\nれんぞくでいれないで\n\nあー…\n\nこんにちは…\n（ごじうにんぎゃりーがふえた）\n\nすぱーん\n（ないすしょっと！）\n\nないっしょー！！！\nわー！！！\n\nおおおおお\nわるくないかもー\n\nすぱっ\n（へんなほうこう）\n\n…\nくすくすくすくす\n\nいらないよ！\nかんじわるいよ！\nけしてよ！\n\nへらすには\nひだり、した、ひだりした、みぎした、ひだり、みぎ、した、みぎしたをいれる？？\n\nなんいどにさがありすぎるよ！\nああ、ひとりもけせない！\n\nかえってー！！！\n\nけんちこです\n\nげつよよびだー！\nおー！\nあさたのゆーきうを\nかちとれー！\n\nんでわいてきます！\n（きりり）\n\nちょーちょーちょーちょーちょーあいしてゆかやねー♥♥♥♥","sender":"健介さん"},{"time":"19:57","sender":"由美さん","body":"帰ります！"}]},{"date_header":"2026年9月8日（火）","messages":[]},{"date_header":"2026年9月9日（水）","messages":[{"body":"きょよはくもってるー\nふらないといいなー\n（しゅごごごごーーっ）\n\nきのーは\nきのー？\nきのー…\nなんかすごくいいひだった\nきがする…\n（しゅごごごごーーっ）\n\nうにゃにゃん\n\nあっ、どあとぅーごるふにゃん\nなんかびしょぬれで\nたいへんそう…\nだいじょぶー？\n\nにゃーうにゃーうにゃんにゃ\n\nふんふん\nあたらしい\nおきゃくさまが\nきにいって\nちょうじかん\nたいざいしてた？？\n\nへー、\nすごいねー\nはやってるねー\nで、なんで\nびしょぬれなのー？\n\nうにゃんにゃにゃうにゃーにゃ\n\nふんふん\nおきゃくさまがくると\nなぜか\nあめがひどくなって\nしんすいしそうになるから\nひっしで\nみずをかきだしてる？？\n\nえっ？\nなにそれ？\nおきゃくさまが\nあめをつれてくる？\nあめおとこ？？\n\nにゃんうにゃーうにゃんにゃん\n\nふんふん\nいまわだいの\nせんじょうこうすいにゃん？\n\nえっ？あの？\nでんせつの？\nせんじょうこうすいにゃん？\nやつがとおったあとには\nかわしかできないっていうあの！？\n\nえー\nすっごーい！\nゆうめいじんじゃん！\nさいんもらってきてー\nあっ、これしきしとぺんね！\nちゃんとゆせいにしてあるからー\n\nあっ、けんちこさん\nどあとぅーごるふにゃんに\nちょーゆうめいじんの\nおきゃくさんが！\nさいんほしーよねー\nけーんちーこさーん","time":"07:39","sender":"由美さん"},{"time":"08:20","sender":"健介さん","body":"あの…ずっとふぁんでした！\nきゃっ\n\nさいんくださーい\n\nあ、ちかづかないで\nそのままうごかないで\n\nきのーも\nもーこわくてこわくて\nすごいなーって\n\nふあんでふあんで\nずっとふあんでした…\n\nあ、さいんありがとう！\nへやにかざります！\n\nいましめとして…\n\nあ、ちかづかないで\nつよい\nあめつよいから\nいたいいたい\nはなれてー！\n\nふう\nそういえばきのー\nどあとぅごるふにゃん\nらいんくれてたよね\nなるべくくるなって\n\nあれはせんじょうこうすいたいにゃんがいたからかー\n\nあ、すっかりなかよくなった？\nそうなんだー\nでも、おおあめだとごるふできないよー\nおくないだからできてるけど\n\n…あ、きづいてなかったんだ\n\nびみょうなくうき！\n\nあー！\nあめがつよくなったー！！\nにげろー！\n\nけんちこです\n\nちょっとふられちゃったー\nかえりはだいじょぶだといーなー\n\nきょよもひるにふりそーだから\nきをつけてね！\n\nではいてきまーす\n\nちょーちょーちょーげきうるとらすんごいあいしてゆかやねー♥♥♥♥"},{"time":"12:17","body":"やったー！\nあたったー！","sender":"由美さん"},{"time":"12:18","sender":"健介さん","body":"すごーい！\nすきなときにつかってね！\nたのしい？たのしい？"},{"sender":"由美さん","time":"12:20","body":"ちょーたのしい！\nありがとーーっ！！\n\nちょー愛してるよ❤️❤️❤️"},{"time":"12:21","body":"うれしい！\nたくさんまわしてね！\nしゅきー♥♥♥","sender":"健介さん"},{"time":"12:21","body":"いっぱいまわすんだー！\n\nしゅきーーーっ❤️","sender":"由美さん"},{"time":"17:07","sender":"由美さん","body":"一等でたーーーーっ！！！\n\nあっ、遊んでないから！\nちょっとだけ休憩してただけだからー！！"},{"time":"17:09","sender":"健介さん","body":"おめでとー！！！\nねこのほん、かってあげるね！！"},{"body":"やったーーーっ！\n\nではしごとにもどります！\n（すちゃっ！）","sender":"由美さん","time":"17:10"},{"body":"お待たせしました！\n帰ります！","time":"21:13","sender":"由美さん"}]},{"date_header":"2026年9月10日（木）","messages":[{"body":"きょよはくもってるー\nそしてちょっとさむーい\n（しゅごごごごーーっ）\n\nきのーはせんじょうこうすいにゃん\nさいんくれたけど\nべたべただったなー\nゆせいぺんが\nながれるほどの…\n（しゅごごごごーーっ）\n\nうにゃにゃにゃ\n\nあっ、どあとぅーごるふにゃん\nきょよはひとりなのー？\n\nにゃーうにゃーうにゃんにゃにゃ\n\nふんふん\nおきゃくさまから\nしんすいがひどくて\nごるふができないという\nくれーむがあいついだので\nしばらく\nきょりをおくことにした？\n\nあっ、うん\nごるふきにいってたのかなー\n\nせんじょうこうすいにゃんは\nなっとくしたのー？\n\nうにゃんにゃうにゃーにゃん\n\nふんふん\nかいひをはらってるんだから\nしようするけんりがあるって\nごねてた？\n\nあっ、おかねとってたんだ\nともだちじゃなかった\nたしかにかいいんさまなら\nだいじにしないと\n\nにゃーうにゃーうにゃんにゃにゃ\n\nふんふん\nひとりのかいひよりも\nそれいがいのひとの\nかいひのほうが\nあっとうてきにおおい？\n\nあっ、うん\nそれはまぁ、そうなんだけど…\nいがいとおかねに\nこだわるなー\n\nうにゃんにゃにゃうにゃーにゃ\n\nふんふん\nぎゃんぶるで\nつくったしゃっきんを\nかえさないと\nこわいひとたちが\nいえに…\n\nえっ？\nぎゃんぶる？\nしゃっきん？？\nなにしてるの？？\n\nにゃーうにゃーうにゃんにゃにゃ\n\nふんふん\nあきじかんに\nちょっとだけの\nぱちんこが？\nきがついたら\nばくだいな\nしゃっきんに！？\n\nなにやってるの？\nごるふとか\nなんかおしゃれな\nかんじかとおもったら\nまさかの\nぱちんかす？！\n\nうにゃんにゃにゃーにゃうにゃ\n\nふんふん\nでもいまは\nちょっとずつ\nちゃんと\nおかねをかえしてる？\n\nあっ、うんうん\nそっかー\nこころをいれかえて\nがんばってるんだねー\n\nてぃろりろりーん♪\n（めーるのちゃくしんおん）\n\nあれっ、どあとぅーごるふから\nめーるだー\nなんだろー\n\nふんふん\nこんげつのかいひが\nしはらわれてません？\n\n…\nえっ？\nあれっ？\nこんげつから\nげんきんの\nおしはらいになったって\nどあとぅーごるふにゃんに\nちょくせつ\nおかねわたしたよね？\n\nって、いない！？\nあんなところに！？\n\nこらーーーっ！\nまてーーーっ！！\n\nあっ、けんちこさん\nそのねこつかまえてー\nすてきなかんじで\nまじでやばいやつだったよー\nけーんちーこさーん","sender":"由美さん","time":"07:41"},{"body":"やべーやつだ！\nいっけんふつうなしんしが\nいちばんやっかいなさぎしなんだ！\n\nでもなんかー\nがっかりだなー\nどあとぅごるふにゃんがさぎしなんてー\nがっかりだなー\nあー、どあとぅごるふにゃん！\nうにちゃんのかいひをかえせー\n\nん？\nもらってない？\nうそだー\nげんきんでわたしたんだぞー\n\nほうほう\nさいきんどあとぅごるふにゃんのなをかたる\nにせものがいる？\nそんなばかなー\nみまちがえるものかー\n\nかってにげんきんでちょうしゅうして\nこまってる？？？\nそもそもしゃっきんなんかしてない？\n\nんー\nなんかー\nりあるだなー\n\nじゃ、いっしょにつかまえるか\n\nあ、あんなところに\nどあとぅごるふにゃんそっくりなねこが！\n（はやい）\n\nこらー\nだれかしらんが…\n？？？\nおなじひと？？\nあれ？\nどあとぅごるふにゃんがにひきいる？？\n\nそっちはめいえきてん？\nまさかのちぇーんてん？\nおれはやってない？？？\n\nああー\nもう\nなにがなんだかー！！\n\nけんちこです！\n\nもくよよびだー！\nまかせとけー！\n（なにを）\n\nきょよも\nねこでいやされますよよに！\n\nんでわいてくゆねー\n\nちょーちょーちょーちょーあいしてゆかやねー♥♥♥♥","time":"08:20","sender":"健介さん"},{"body":"お待たせしました！\n帰ります！","time":"20:56","sender":"由美さん"}]},{"date_header":"2026年9月11日（金）","messages":[{"sender":"健介さん","time":"08:26","body":"いいですか？\n\nにゃー\n\nあなたたちのなかにさぎしがいます\n\nにゃー！にゃー！\n\nおちついてください。さわがないで\n\nにゃー\n\nはい、ひびのてんさん\n\nにゃー！\n\nたしかにね、あいちにそんなわるいやつがいるとはおもいたくないけどね\n\nにゃー！！\n\nはい、しぶやてんさん\n\nにゃーにゃー\n\nそうね、だからといってとうきょうにはんにんがいるとはかぎらないからね\n\nにゃー！！！\n\nおちついて！おちついてください！\nふう\nまさかぜんこくににひゃくてんぽもあるなんて\nこのなかにさぎしがいるはずなんだけどなー\n\nえ？しゅっせきしてないどあとぅごるふにゃんがいる？\nかすかべてん？？\n\nあやしい！\nあいにいかなきゃ！\n\nえ？\nうにさまがちょうどかすかべしゅっちょう？？？\n\nなんてぐうぜん！\nどあとぅごるふにゃんかすかべてんをしらべてきて！\nきをつけてねー！！\n\nけんちこです\n\nねこはまかせろー！\nよるはかなやままでむかえにいくかやね！\n\nんでわいてきまーす\n\nちょーちょーちょーあいしてゆかやねー♥♥♥♥"},{"sender":"由美さん","body":"すごい！\nまさかつづきがよめるなんて！！\n\n今日は朝からごめがとう。\n健介さんも早起きさせてごめがとう。\n無理しないでね。\n\nはっ、けんちこさんから\nしれいが！？\n\nサギシカスカベテンカモ？\n\nさぎ？\nかも？\nとりにく？\nこんばんのおかず？？\n\nわかったー！\nきょよは\nとりにくたべたいんだー\n（かすかべてんは？？）\n\nよーし\nかすかべの\nしょしんしゃのもりで\nとりにくをさがすんだー\n（かすかべにもしょしんしゃのもりが？）\n\nいくぞー\nねこー！\n\nではひとかり\nいってくるねー\nけーんちーこさーん","time":"08:37"}]}],"week_start":"2026-09-07","week_title":"9月 第2週（2026/09/07 〜 2026/09/11）","week_end":"2026-09-11"}'::jsonb)
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, kana = EXCLUDED.kana, motif = EXCLUDED.motif, week_title = EXCLUDED.week_title, week_info = EXCLUDED.week_info, updated_at = NOW();

INSERT INTO api.master_settings (key, value) VALUES
